CREATE TABLE users(id TEXT PRIMARY KEY, name TEXT NOT NULL, country TEXT NOT NULL DEFAULT 'XX', xp INTEGER NOT NULL DEFAULT 0, coins INTEGER NOT NULL DEFAULT 0, skin INTEGER NOT NULL DEFAULT 0, email TEXT UNIQUE, password TEXT, banned INTEGER NOT NULL DEFAULT 0, ref TEXT REFERENCES users(id), created TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sessions(token TEXT PRIMARY KEY, uid TEXT NOT NULL REFERENCES users(id), expires INTEGER NOT NULL);
CREATE TABLE results(match TEXT NOT NULL, uid TEXT NOT NULL REFERENCES users(id), mode TEXT NOT NULL, win INTEGER NOT NULL, rounds INTEGER NOT NULL, score INTEGER NOT NULL, online INTEGER NOT NULL, created TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(match,uid));
CREATE INDEX results_player ON results(uid,created);
CREATE TABLE unlocks(uid TEXT NOT NULL REFERENCES users(id), skin INTEGER NOT NULL, PRIMARY KEY(uid,skin));
CREATE TABLE friends(uid TEXT NOT NULL REFERENCES users(id), friend TEXT NOT NULL REFERENCES users(id), PRIMARY KEY(uid,friend));
CREATE TABLE claims(uid TEXT NOT NULL REFERENCES users(id), mission TEXT NOT NULL, period TEXT NOT NULL, PRIMARY KEY(uid,mission,period));
CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE reports(id INTEGER PRIMARY KEY, uid TEXT NOT NULL REFERENCES users(id), target TEXT NOT NULL REFERENCES users(id), reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', created TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
